def calculate_b_squared(a):
    # b^2 = (a^3 - 2*a^2 - a) / (a - 2)
    numerator = a**3 - 2*a**2 - a
    denominator = a - 2

    if denominator == 0:
        return None # Should not happen for the tested values

    return numerator / denominator

test_cases = [0, 1, 3, 0.5, -1]
results = {}

for a in test_cases:
    b2 = calculate_b_squared(a)
    results[a] = b2

print("Calculations for b^2:")
for a, b2 in results.items():
    print(f"a = {a}, b^2 = {b2}")

